package md.utm.messaging.broker; import md.utm.messaging.contracts.*; import java.io.*; import java.net.Socket;
public final class ConsumerConnection implements AutoCloseable { private final String consumerId,destination; private final Socket socket; private final BufferedReader reader; private final BufferedWriter writer; public ConsumerConnection(String id,String dest,Socket s,BufferedReader r,BufferedWriter w){consumerId=id;destination=dest;socket=s;reader=r;writer=w;} public String consumerId(){return consumerId;} public String destination(){return destination;}
 public synchronized boolean deliver(MessageEnvelope m,int attempt)throws IOException{JsonLineProtocol.write(writer,TransportFrame.delivery(m,attempt)); TransportFrame f=JsonLineProtocol.read(reader); if("ack".equals(f.kind())&&m.id().equals(f.messageId()))return true; if("nack".equals(f.kind())&&m.id().equals(f.messageId()))return false; throw new IOException("Expected ACK/NACK for message "+m.id());} public void close()throws IOException{socket.close();}}
